// Run Config for the score-only script doctor. Ruled by Tee 2026-10-24: score
// the hand-loaded Scripted rows, never rewrite them. This workflow runs only
// when a person starts it; it has no schedule and no webhook.
// FIRST_RUN_LIMIT applies until one score-only doctor line has been written to
// either table, so the first run scores a single row and proves the provider
// and the recall before the rest are spent. A run with no recall stops at
// Recall Required and writes nothing, so a written line always had the recall.
// ROW_LIMIT applies to every run after that one. Each run is still started by
// hand.
// ONLY_ROWS, when it is not empty, limits the run to the rows it names, written
// as 'TQO:49' or 'NCO:30'. A name that is not an eligible row stops the run.
// WRITE false makes a measurement run, ruled by Tee 2026-10-24 to see how far
// one row's score moves between runs: every step runs and the doctor is paid,
// and nothing is written to either table. The run report lists each score.
// READS is how many times each row is read, ruled by Tee 2026-10-24 after the
// same request scored 85, 100 and 90: the strictest read is what is written.
return [{ json: { FIRST_RUN_LIMIT: 1, ROW_LIMIT: 20, ONLY_ROWS: ['TQO:49'], WRITE: false, READS: 3 } }];

// Select Rows. Picks the Scripted rows that carry a script and no doctor line,
// TQO first and then NCO, each in row order. A row that already carries a
// doctor line is never scored again, so a run that stops halfway is finished
// by running it again. The doctor line is read with the same pattern as the QC
// Doctor Gate and Preflight: Can This Clear? in TQO FINAL V5.
// Until a score-only line exists on a Scripted row in either table, a run takes
// FIRST_RUN_LIMIT rows. Once one does, it takes ROW_LIMIT. Only Scripted rows
// are read, so if every scored row has moved on, the next run is one row again.
const cfg = $('Run Config').first().json;
const whole = (n) => Number.isInteger(n) && n > 0;
if (!whole(cfg.FIRST_RUN_LIMIT) || !whole(cfg.ROW_LIMIT)) {
  throw new Error('Run Config FIRST_RUN_LIMIT and ROW_LIMIT must be whole numbers above 0, and they read ' + JSON.stringify(cfg.FIRST_RUN_LIMIT) + ' and ' + JSON.stringify(cfg.ROW_LIMIT) + '.');
}
if (!Number.isInteger(cfg.READS) || cfg.READS < 1 || cfg.READS > 5) {
  throw new Error('Run Config READS must be a whole number from 1 to 5, and it reads ' + JSON.stringify(cfg.READS === undefined ? null : cfg.READS) + '.');
}
if (typeof cfg.WRITE !== 'boolean') {
  throw new Error('Run Config WRITE must be true or false, and it reads ' + JSON.stringify(cfg.WRITE === undefined ? null : cfg.WRITE) + '.');
}
const only = Array.isArray(cfg.ONLY_ROWS) ? cfg.ONLY_ROWS.map(String) : [];
const DOCTOR = /\|\s*doctor\s+(\d+(?:\.\d+)?)\/100\s+([^|\n]*?)\s*(?=\||\n|$)/;
const SCORE_ONLY = /\|\s*doctor\s+\d+(?:\.\d+)?\/100\s+(?:PASS|NEEDS_REVISION)\s*\|\s*score only, no rewrite\b/;
const SHOWS = [
  { show: 'TQO', tableRef: '2GtmrFcTNqVMbddh', node: 'Get TQO Scripted Rows' },
  { show: 'NCO', tableRef: 'DSH1tn4TZjzAEKxp', node: 'Get NCO Scripted Rows' }
];
const eligible = [];
const counts = [];
let proven = false;
for (const s of SHOWS) {
  const rows = $(s.node).all().map(i => i.json).filter(j => j && j.id !== undefined && j.id !== null)
    .sort((a, b) => Number(a.id) - Number(b.id));
  let scored = 0, empty = 0, other = 0;
  for (const r of rows) {
    const history = String(r.score_history || '');
    if (SCORE_ONLY.test(history)) proven = true;
    if (String(r.status) !== 'Scripted') { other++; continue; }
    if (!String(r.script || '').trim()) { empty++; continue; }
    if (DOCTOR.test(history)) { scored++; continue; }
    eligible.push({ ...r, nco: s.show === 'NCO', __show: s.show, __tableRef: s.tableRef, __key: s.show + ':' + r.id });
  }
  counts.push(s.show + ' ' + rows.length + ' Scripted read, ' + scored + ' already carry a doctor line, ' + empty + ' have no script' + (other ? ', ' + other + ' not Scripted' : ''));
}
const unknown = only.filter(k => !eligible.some(r => r.__key === k));
if (unknown.length) throw new Error('ONLY_ROWS names ' + unknown.join(', ') + ', which is not a Scripted row with a script and no doctor line. ' + counts.join('; ') + '.');
const limit = proven ? cfg.ROW_LIMIT : cfg.FIRST_RUN_LIMIT;
const pool = only.length ? eligible.filter(r => only.includes(r.__key)) : eligible;
const picked = pool.slice(0, limit);
const note = 'select: ' + counts.join('; ') + '; ' + eligible.length + ' eligible; '
  + (proven ? 'a score-only line exists, so the limit is ROW_LIMIT ' : 'no score-only line yet, so the limit is FIRST_RUN_LIMIT ') + limit
  + '; ' + picked.length + ' scored this run (' + picked.map(r => r.__key).join(', ') + ')';
if (!picked.length) throw new Error('No row to score. ' + note + '.');
return picked.map(r => ({ json: { ...r, __selectNote: note } }));

// DT alias shim (TQO migration): expose Airtable-style names + fields{} view.
const MAP={status:'Status',system_status:'System Status',brand:'Brand',show:'Show',content_id:'Content ID',video_title:'Video Title',body:'Body',script:'Script',description:'Description',tags:'Tags',broll_keywords:'Broll Keywords',angle:'Angle',function:'Function',notes:'Notes',episode_row:'Episode Row',last_feedback:'Last Feedback',video_url:'Video URL',published_url:'Published URL',platform_packaging:'Platform Packaging',os_28_status:'OS 28 Status',cold_open:'COLD OPEN',hook_type:'Hook Type',ai_disclosure:'AI Disclosure',claim_validity:'Claim Validity',recheck_by:'Recheck By',primary_subject:'Primary Subject',thumbnail_headline:'Thumbnail Headline',est_seconds:'Est Seconds',rubric_average:'Rubric Average',correction_attempts:'Correction Attempts',render_attempts:'Render Attempts',human_review:'Human Review',qc_verdict:'QC Verdict',qc_score:'QC Score',qc_findings:'QC Findings',score_history:'Score History',manifest:'Manifest',topic:'Topic',idea:'Idea',idea_score:'Idea Score',idea_score_breakdown:'Idea Score Breakdown',routing:'Routing',channel:'Channel',asset_type:'Asset Type',parent_record:'Parent Record',aspect_ratio:'Aspect Ratio',season:'Season',episode:'Episode',attached_offer:'Attached Offer',canonical_rule_id:'Canonical Rule ID',atomized_at:'Atomized At',live_links:'Live Links',virality_score:'Virality Score'};
return $input.all().map(it=>{const j=it.json||{};if(j.id===undefined)return it;const out={...j};const fields={};for(const[s,o]of Object.entries(MAP)){if(s in j){out[o]=j[s];if(j[s]!==null)fields[o]=j[s];}}out.fields=fields;out.createdTime=j.createdAt;return {json:out};});

// Run Report. One line per row scored. The run ends in error when any row was
// not written, so a partial run never reads as a clean one; the rows that were
// written stay written, and running again picks up only the rest. A PASS at 90
// or above is what the QC Doctor Gate and Preflight read as a clear doctor
// line. It clears that one check and nothing else on the row.
// In a measurement run (Run Config WRITE false) nothing is written on purpose:
// a row the doctor scored is listed as measured, and only a row that could not
// be scored ends the run in error.
const FLOOR = 90;
const results = $input.all().map(i => i.json);
if (!results.length || results.some(r => !r || r.rowId === undefined || typeof r.written !== 'boolean')) {
  throw new Error('Run Report could not read the loop results: ' + JSON.stringify(results).slice(0, 600));
}
const measure = $('Run Config').first().json.WRITE === false;
const written = results.filter(r => r.written);
const cleared = written.filter(r => r.verdict === 'PASS' && Number(r.score) >= FLOOR);
const measured = results.filter(r => !r.written && measure && r.ok === true);
const failed = results.filter(r => !r.written && !(measure && r.ok === true));
const lines = results.map(r => r.show + ' row ' + r.rowId + (r.title ? ' "' + r.title + '"' : '') + ': '
  + (r.written
    ? r.verdict + ' ' + r.score + '/100, ' + (r.verdict === 'PASS' && Number(r.score) >= FLOOR ? 'the doctor line clears at ' + FLOOR : 'the doctor line holds the row')
    : measured.includes(r)
      ? 'MEASURED, NOT WRITTEN: ' + r.verdict + ' ' + r.score + '/100. DIAGNOSIS: ' + ((String(r.feedback || '').match(/\nDIAGNOSIS: ([^\n]*)/) || [])[1] || 'none given')
      : 'NOT WRITTEN, ' + r.reason));
let note = '';
try { note = String($('Select Rows').first().json.__selectNote || ''); } catch (e) { note = ''; }
const summary = (measure ? 'MEASUREMENT RUN, Run Config WRITE is false: ' + measured.length + ' row(s) scored and nothing written.\n' : '')
  + 'Score-only doctor run: ' + results.length + ' row(s), ' + written.length + ' written, '
  + cleared.length + ' clear the doctor check at ' + FLOOR + ', ' + failed.length + ' not written.\n'
  + lines.join('\n') + (note ? '\n' + note : '');
if (failed.length) throw new Error(summary);
return [{ json: { summary, results } }];

// DEVON Recall: Merge (added 15 Sep 2026). Ruled by Tee on an inline card:
// the writer is grounded by retrieval from his own record plus capture of his
// edits. This node folds two things onto the idea row before Build Script
// Prompt reads it: the devon-soul recall for this topic, and the newest
// exemplars of how Tee rewrote earlier machine drafts. Both are optional. A
// recall that fails (probe execution 86 on 15 Sep 2026 returned 401 because
// the stored credential does not match the service) is named in
// devonRecallNote and the script is still written; nothing here blocks.
const row = $('One Idea at a Time').first().json;
let recallText = '';
let recallNote = '';
try {
  const res = $('DEVON Recall: Ask').first().json || {};
  const code = Number(res.statusCode);
  let body = res.body;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
  if (code === 200 && body && Array.isArray(body.records)) {
    const recs = body.records.filter(r => r && String(r.text || '').trim()).slice(0, 7);
    recallText = recs.map(r => '- [' + String(r.source || 'soul') + ', score ' + (Number(r.score) || 0).toFixed(2) + '] ' + String(r.text).replace(/\s+/g, ' ').trim().slice(0, 600)).join('\n');
    recallNote = 'DEVON recall: ' + recs.length + ' record(s), ' + (body.tee_count ?? '?') + ' from Tee and ' + (body.devon_count ?? '?') + ' from DEVON' + (Array.isArray(body.errors) && body.errors.length ? '; partial: ' + body.errors.join('; ') : '');
  } else {
    const detail = body && body.detail ? String(body.detail) : (res.error ? String(res.error.message || res.error) : '');
    recallNote = 'DEVON recall unavailable (HTTP ' + (code || 'none') + (detail ? ', ' + detail.slice(0, 120) : '') + '); the script was written without it';
  }
} catch (e) {
  recallNote = 'DEVON recall did not run: ' + e.message;
}
const exemplars = $input.all().map(i => i.json || {}).filter(j => String(j.tee_script || '').trim());
const squeeze = (s, n) => String(s || '').replace(/\s+/g, ' ').trim().slice(0, n);
const exemplarText = exemplars.map((j, i) => [
  'Exemplar ' + (i + 1) + ' (' + String(j.topic || 'untitled') + ', captured ' + String(j.captured_at || '').slice(0, 10) + ', ' + (j.machine_words || '?') + ' machine words to ' + (j.tee_words || '?') + ' after Tee):',
  'MACHINE DRAFT OPENED: ' + squeeze(j.machine_script, 400),
  'TEE REWROTE IT AS: ' + squeeze(j.tee_script, 900)
].join('\n')).join('\n\n');
return [{ json: { ...row, devonRecall: recallText, devonRecallNote: recallNote, devonExemplars: exemplarText, devonExemplarCount: exemplars.length } }];

const nco = $json.nco === true;
return [{ json: nco ? {
  show: 'NCO', channel: 'NCO Forge', tableId: 'nco_content', tableRef: 'DSH1tn4TZjzAEKxp',
  brand: 'nco', kicker: 'NCO FORGE',
  // Brand hierarchy from the Aug 2026 audit: brand, then emotion, then position.
  tagline: "Leaders aren't born. They're forged.",
  positioning: 'Where doctrine ends and leadership begins.',
  tagline2: 'Built by Discipline. Living on Purpose.',
  thesis: 'NCO Forge is where military experience becomes leadership judgment. The situations nobody can teach you from a slide.',
  requiredTags: ['NCO Forge'],
  scriptLimit: 2, promoteLimit: 1, packageLimit: 3,
} : {
  show: 'TQO', channel: 'The Quiet Operator', tableId: 'tqo_content', tableRef: '2GtmrFcTNqVMbddh',
  brand: 'tqo', kicker: 'THE QUIET OPERATOR',
  tagline: 'AI Strategy for the Next Economy.',
  positioning: 'Leverage for the people the AI economy is quietly repricing.',
  tagline2: 'Quiet Leverage. Real Results.',
  thesis: 'The Quiet Operator is where professional judgment survives automation. Receipts, not predictions.',
  requiredTags: [],
  scriptLimit: 2, promoteLimit: 1, packageLimit: 3,
} }];

// Recall Required. The doctor treats any first person claim that is not in
// TEE'S RECORD as invented, so a score taken without the DEVON recall is not a
// score of the script as Tee wrote it. When the recall does not answer, the
// run stops here, before the provider is paid, and says why. Rows written
// earlier in the run stay written, and running again picks up the rest. The
// test is the one DEVON Recall: Merge applies, HTTP 200 with a records array,
// which may be empty, plus one more: the soul service answers 200 with an
// errors entry beginning "tee-soul-layer unavailable" when Tee's own index did
// not answer, and that is a recall without Tee's record. An entry about DEVON's
// index alone does not stop the run.
const res = $('DEVON Recall: Ask').first().json || {};
const code = Number(res.statusCode);
let body = res.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
const teeDown = body && Array.isArray(body.errors) && body.errors.some(e => String(e).startsWith('tee-soul-layer unavailable'));
if (!(code === 200 && body && Array.isArray(body.records)) || teeDown) {
  const row = $('One Idea at a Time').first().json;
  const merged = $input.first() ? $input.first().json : {};
  throw new Error('The DEVON recall did not answer for ' + String(row.__key || row.id) + ', so it was not scored and the run stopped before calling the provider. '
    + String(merged.devonRecallNote || 'No recall note.') + ' Rows written earlier in this run stay written; run it again once the recall answers.');
}
return $input.all();

// Script: Hydrate from Row. Tee ruling 2026-10-01: the pipeline must USE a
// script that already exists on the row instead of rewriting it. This node
// shapes the row's stored script into the same d-shape Build Doctor Prompt
// expects from Parse Script JSON, so an existing script enters the chain at
// the doctor, not at the writer. Nothing here invents content: the title,
// description, b-roll, learning objective and checklist come from the row
// where they exist, empty where they do not.
const row = $('One Idea at a Time').first().json;
// Score-only copy. The DT shim builds fields from its MAP only, which has no
// learning_objective and spells the b-roll column Broll Keywords, so the live
// line, const f = row.fields || row, read neither and the doctor was told the
// learning objective was none returned. The row's own columns are read too,
// and the shim's names win where both exist.
const f = { ...row, ...(row.fields || {}) };
const script = String(f.Script ?? f.script ?? '').trim();
if (!script) {
  throw new Error('Script: Hydrate from Row reached with an empty script. This node only runs for rows that already carry one.');
}
const list = (v) => Array.isArray(v) ? v.map(s => String(s).trim()).filter(Boolean) : [];
const tags = String(f.Tags ?? f.tags ?? '').trim();
const broll = String(f['B-Roll Keywords'] ?? f.broll_keywords ?? '').trim();
return [{
  json: {
    recordId: row.id,
    title: String(f['Video Title'] ?? f.video_title ?? f.Topic ?? '').trim(),
    script,
    description: String(f.Description ?? f.description ?? '').trim(),
    tags,
    broll,
    learningObjective: String(f.learning_objective ?? '').trim(),
    checklist: list(f.checklist),
    __source: 'existing-row-script',
  }
}];

// Doctor Sources, ruled by Tee 2026-10-07 with the Sources Rule: the doctor sees
// the approved sources, so it keeps a sourced figure and cuts any other. Both
// shows, NCO from the same day's second ruling.
const row = $('One Idea at a Time').first().json;
const j = $input.first().json;
if (!j.claudeBody) return [{ json: j }];
let list = [];
try { const l = JSON.parse(String(row.sources || '')); if (Array.isArray(l)) list = l.filter(x => x && x.url && x.quote); } catch (e) { list = []; }
const block = list.length
  ? 'APPROVED SOURCES (the only figures and named sources that may stand):\n' + list.map((s, i) => '[S' + (i + 1) + '] ' + (s.origin || s.publisher) + ', reported by ' + s.publisher + ': "' + (s.quote_text || s.quote) + '"').join('\n')
  : 'APPROVED SOURCES: none. No figure, percentage, dollar amount or named study may stand.';
const rule = 'SOURCES: a figure, percentage, dollar amount or named study that is not in APPROVED SOURCES is invented. Cut it or make the point without it. Never change a sourced figure or the year it belongs to.';
const cb = j.claudeBody;
const msgs = (cb.messages || []).slice();
if (msgs.length) msgs[0] = { ...msgs[0], content: block + '\n\n' + String(msgs[0].content || '') };
return [{ json: { ...j, claudeBody: { ...cb, system: String(cb.system || '') + '\n' + rule, messages: msgs } } }];

// Output ceiling for the script doctor.
// This is the largest output in the script lane: on a REPAIRED verdict it
// returns the whole script again, plus the preservation list, the diagnosis and
// the notes. Truncation here does not throw. Parse Doctor Verdict passes the
// original draft through unedited and marks it UNCHECKED, which means you lose
// the audit silently rather than loudly.
const MAX_TOKENS = 12000;

const j = { ...$json };
if (j.body) j.body = { ...j.body, max_tokens: MAX_TOKENS };
if (j.claudeBody) j.claudeBody = { ...j.claudeBody, max_tokens: MAX_TOKENS };
// Cerebras gpt-oss-120b carries this call from 15 Sep 2026, on Tee's ruling that
// every model call in this workflow moves off Anthropic. The prompt builder still
// emits the Anthropic shape, so the whole swap is this conversion here and one
// extraction line in the parser downstream. max_completion_tokens on Cerebras
// INCLUDES the model's reasoning tokens, which is why the ceiling above stays
// generous rather than trimmed to the prose.
const SUFFIX = '\n\nOutput rules that override anything above: never use an em dash or an en dash anywhere in any field, use a comma, a full stop or the word to instead; write the full length the brief asks for, never shorter.';
const toCerebras = (b) => {
  if (!b || !Array.isArray(b.messages)) return b;
  const sys = (typeof b.system === 'string' && b.system) ? [{ role: 'system', content: b.system + SUFFIX }] : [];
  return { model: 'gpt-oss-120b', messages: [...sys, ...b.messages], max_completion_tokens: MAX_TOKENS, reasoning_effort: 'medium', response_format: { type: 'json_object' } };
};
if (j.body) j.body = toCerebras(j.body);
if (j.claudeBody) j.claudeBody = toCerebras(j.claudeBody);
return [{ json: j }];

// Score Only: Final Word. Token Budget: Doctor, copied from the live lane, ends
// the system message with output rules written for the full pass, and one of
// them, "write the full length the brief asks for, never shorter", says it
// overrides anything above. In a score-only pass that reads as a request for a
// rewrite. This line comes last and says which of those rules still stands.
//
// Ruled by Tee 2026-10-24 after execution 4300. The doctor held row 49 for a
// learning objective that "appears after several sentences instead of within
// the first 30 seconds", when it starts at word 31, and asked for "the second
// occurrence" of it to be removed, when the script speaks it once: it had read
// the LEARNING OBJECTIVE field line as script. Its reasoning guessed the
// position ("Probably not before 30 seconds") rather than counting it. So two
// things go into the user message, just above SCRIPT:. The first is where the
// learning objective is spoken, measured by the Script Gate's own rule in TQO
// FINAL V5: word for word, ignoring case and punctuation, inside the first 70
// words, which the gate counts as the first 30 seconds. The doctor is told the
// fact instead of being left to guess it. The second says which lines are the
// brief and which are the script. NCO has no learning objective line, so it
// gets the second only.
//
// Ruled by Tee 2026-10-24 on a card: first person that only addresses the
// viewer and claims no deed, sight or advice is allowed in his voice. Row 49's
// only first person sentence, "I am talking to the person who has spent years
// handling problems other people never even saw.", was flagged as an invented
// first person claim in three of five runs and passed in two, and the Script
// Gate's first person patterns pass it. VOICE says so in the system message,
// for both shows, just before FINAL. Nothing else in the request changes.
// Sharpened by Tee the next day, after execution 4364: one read of three still
// marked the line down, reading "the person who has spent years" as Terrance.
// VOICE now says that person is the viewer.
const VOICE = '\n\nRuled by Tee: first person that only addresses the viewer and claims no deed, sight, hearing or advice, as in "I am talking to the person who has spent years handling problems other people never even saw.", is his voice and stands. In that line, the person who has spent years handling problems other people never even saw is the viewer being addressed, not Terrance, so the line says nothing about what he has done. It is not a first person claim and is never marked down. The rule against invented experience still applies to everything Terrance is said to have done, seen, heard or advised.';
const FINAL = '\n\nScore only, and this overrides the full-length rule above: return only the JSON object the score-only contract names, with no script, title, description or b-roll field. Keep each note to a few sentences that describe a repair without writing it out. The rule against em and en dashes still stands.';
// The Script Gate's window and its normaliser, copied from Script Gate: Quality.
// Keep the two equal; score_only.test.mjs checks them against the export.
const LO_WINDOW = 70;
const norm = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(Boolean).join(' ');
const MARK = '\n\nSCRIPT:\n';

const j = { ...$json };
const b = j.claudeBody;
if (!b || !Array.isArray(b.messages) || !b.messages.length || b.messages[0].role !== 'system') {
  throw new Error('Score Only: Final Word expected the request to open with a system message, and it does not.');
}
if (b.messages.length !== 2 || b.messages[1].role !== 'user') {
  throw new Error('Score Only: Final Word expected one system message and one user message, and the request carries ' + b.messages.map((m) => m && m.role).join(', ') + '.');
}
const d = $('Build Doctor Prompt').first().json.original || {};
const script = String(d.script || '');
const content = String(b.messages[1].content);
const at = content.indexOf(MARK);
if (at === -1 || content.slice(at + MARK.length) !== script) {
  throw new Error('Score Only: Final Word could not find the script after SCRIPT: in the user message, so the measured facts were not added and the doctor was not called.');
}
const nco = $('Show Context: Script').first().json.show === 'NCO';

const facts = [];
if (!nco) {
  const tokens = script.split(/\s+/).filter(Boolean);
  const lo = norm(d.learningObjective);
  if (!lo) {
    facts.push('MEASURED BEFORE THIS PASS: no learning objective is stored for this row.');
  } else {
    // The gate's own test, character for character.
    const inside = (' ' + norm(tokens.slice(0, LO_WINDOW).join(' ')) + ' ').includes(' ' + lo + ' ');
    // Where it is spoken: the normalised words of the script, each carrying the
    // number of the script word it came from.
    const flat = [];
    tokens.forEach((t, i) => { for (const w of norm(t).split(' ').filter(Boolean)) flat.push({ w, i }); });
    const want = lo.split(' ');
    const hits = [];
    for (let k = 0; k + want.length <= flat.length; k++) {
      if (want.every((w, x) => flat[k + x].w === w)) hits.push({ from: flat[k].i + 1, to: flat[k + want.length - 1].i + 1 });
    }
    const first = hits[0];
    if (inside !== Boolean(first && first.to <= LO_WINDOW)) {
      throw new Error('Score Only: Final Word measured the learning objective two ways and they disagree, so the doctor was not called.');
    }
    const rule = 'by the rule the Script Gate in TQO FINAL V5 applies (word for word, ignoring case and punctuation, inside the first ' + LO_WINDOW + ' words, which the gate counts as the first 30 seconds)';
    if (!first) {
      facts.push('MEASURED BEFORE THIS PASS, ' + rule + ': the learning objective is not spoken word for word anywhere in the script.');
    } else {
      facts.push('MEASURED BEFORE THIS PASS, ' + rule + ': the learning objective is spoken word for word from word ' + first.from + ' to word ' + first.to + ' of ' + tokens.length + ', '
        + (inside ? 'inside the first ' + LO_WINDOW + ' words. Its position meets the brief; do not mark it down for where it sits.' : 'which is past the first ' + LO_WINDOW + ' words, so its position does not meet the brief.')
        + ' The script speaks it ' + (hits.length === 1 ? 'once' : hits.length + ' times') + '.');
    }
  }
}
facts.push('Every line above SCRIPT: is the brief: the channel, show and editorial direction, the TITLE, DESCRIPTION and BROLL fields, '
  + (nco ? '' : 'the LEARNING OBJECTIVE and CHECKLIST lines, ')
  + 'the APPROVED SOURCES and TEE\'S RECORD. None of those lines is part of the script, and none is a second copy of a script sentence. Only the text after SCRIPT: is the script.');

j.claudeBody = { ...b, messages: [
  { ...b.messages[0], content: String(b.messages[0].content) + VOICE + FINAL },
  { ...b.messages[1], content: content.slice(0, at) + '\n\n' + facts.join('\n') + MARK + script }
] };
return [{ json: j }];

// Score Only: Reads. Ruled by Tee 2026-10-24, after the same request to the
// doctor scored 85, 100 and 90 in three runs (executions 4354 to 4356): every
// row is read READS times and Parse Score Only writes the strictest of them, so
// a lucky single read can never clear a row. Each copy of the request is its
// own call to Run Script Doctor (Cerebras), which runs once per item.
const n = $('Run Config').first().json.READS;
const items = $input.all();
if (items.length !== 1) throw new Error('Score Only: Reads expected one request and received ' + items.length + '.');
return Array.from({ length: n }, (_, i) => ({ json: { ...items[0].json, read: i + 1 } }));

// Parse Score Only. The doctor was told to score and never repair, so the only
// results are PASS or NEEDS_REVISION with a score from 0 to 100. Anything else
// is UNCHECKED and nothing is written: a refused or failed call, a truncation,
// an empty or unreadable reply, a verdict outside those two, and REPAIRED most
// of all, because no repair was made and the QC Doctor Gate would clear it.
// Unlike Parse Doctor Output in TQO FINAL V5, a missing verdict is never PASS,
// and only a completion that finished on its own (finish_reason stop) is read.
// Ruled by Tee 2026-10-24: the row is read READS times and the strictest read
// is written. The score is the lowest of them, and the verdict is PASS only
// when every read is PASS at 90 or above. If any read fails, none is written.
// That holds at READS 1 too: a PASS under 90 is written as NEEDS_REVISION, which
// the QC Doctor Gate and Preflight hold either way.
const FLOOR = 90;
const row = $('One Idea at a Time').first().json;
const ctx = $('Show Context: Script').first().json;
const READS = $('Run Config').first().json.READS;
const stamp = new Date().toISOString();
let recall = '';
try { recall = String($('DEVON Recall: Merge').first().json.devonRecallNote || ''); } catch (e) { recall = ''; }
const base = {
  show: ctx.show, tableRef: ctx.tableRef, rowId: row.id,
  title: String(row.video_title || row.topic || ''), stamp, recall, written: false
};
const fail = (reason) => [{ json: { ...base, ok: false, verdict: 'UNCHECKED', score: null, reason } }];

// One read: a verdict and a score, or the reason it is not a result.
const readOne = (out) => {
  out = out || {};
  const no = (reason) => ({ ok: false, reason });
  if (out.error) return no('the Cerebras call failed: ' + String(out.error.message || JSON.stringify(out.error)).slice(0, 300));
  const choice = Array.isArray(out.choices) ? out.choices[0] : null;
  if (!choice || !choice.message) return no('the Cerebras response carried no completion');
  if (choice.finish_reason === 'length') return no('the completion was truncated at max_completion_tokens');
  if (choice.finish_reason !== 'stop') return no('the completion ended on ' + JSON.stringify(choice.finish_reason === undefined ? null : choice.finish_reason) + ' rather than stop');
  const raw = String(choice.message.content ?? '').trim().replace(/^```(json)?/i, '').replace(/```$/, '').trim();
  if (!raw) return no('the completion was empty');
  let v;
  try { v = JSON.parse(raw); }
  catch (e) {
    const s = raw.indexOf('{'), en = raw.lastIndexOf('}');
    if (s === -1 || en <= s) return no('the completion was not JSON');
    try { v = JSON.parse(raw.slice(s, en + 1)); } catch (e2) { return no('the completion JSON did not parse'); }
  }
  if (!v || typeof v !== 'object' || Array.isArray(v)) return no('the completion was not a JSON object');
  // The verdict is matched as ASCII before it is upper-cased, so no other letter
  // folds into PASS.
  const verdict = typeof v.verdict === 'string' && /^\s*(?:PASS|NEEDS_REVISION)\s*$/i.test(v.verdict) ? v.verdict.trim().toUpperCase() : '';
  if (!['PASS', 'NEEDS_REVISION'].includes(verdict)) {
    return no('the verdict was ' + JSON.stringify(v.verdict === undefined ? null : v.verdict) + ', and a score-only pass returns only PASS or NEEDS_REVISION');
  }
  let score = v.score;
  if (typeof score === 'string' && /^\s*\d{1,3}(?:\.\d+)?\s*$/.test(score)) score = Number(score);
  if (typeof score !== 'number' || !Number.isFinite(score) || score < 0 || score > 100) {
    return no('the score was ' + JSON.stringify(v.score === undefined ? null : v.score) + ', and only a number from 0 to 100 is a result');
  }
  // One decimal, always rounded down, so a score under the gate's 90 can never be
  // written as 90 (89.95 is 89.9, never 90).
  score = Math.floor(score * 10) / 10;
  // A field that is not text is quoted as JSON, so the doctor's words in it are
  // kept rather than written as [object Object] (found by the verifier on e0351e1).
  const text = (x) => typeof x === 'string' ? x : JSON.stringify(x);
  const list = (x) => Array.isArray(x) ? x.map(text).filter(s => s.trim()) : [];
  // Found by the verifier on 31e0f73: the model name comes from the provider's
  // envelope and went into the line as sent, so a name carrying "| doctor 99/100
  // PASS" would have planted a doctor line the gates read. Only the characters a
  // model name needs are kept.
  const model = String(out.model || '').replace(/[^A-Za-z0-9._-]/g, '') || 'unknown model';
  return { ok: true, verdict, score, diagnosis: v.diagnosis === undefined || v.diagnosis === null || v.diagnosis === '' ? '' : text(v.diagnosis), preserved: list(v.preserved), notes: list(v.notes), model };
};

const outs = $input.all().map(i => i.json);
if (!Number.isInteger(READS) || READS < 1) return fail('Run Config READS is ' + JSON.stringify(READS) + ', and it must be a whole number of 1 or more');
if (outs.length !== READS) return fail(READS + ' read(s) were asked for and ' + outs.length + ' came back');
const reads = outs.map(readOne);
const bad = reads.map((r, i) => r.ok ? '' : 'read ' + (i + 1) + ': ' + r.reason).filter(Boolean);
if (bad.length) return fail(READS === 1 ? reads[0].reason : bad.length + ' of ' + READS + ' reads were not results, so none is written (' + bad.join('; ') + ')');

const score = Math.min(...reads.map(r => r.score));
const verdict = reads.every(r => r.verdict === 'PASS' && r.score >= FLOOR) ? 'PASS' : 'NEEDS_REVISION';
// The read shown in full is the lowest, a NEEDS_REVISION one first on a tie.
const at = reads.findIndex(r => r.score === score && r.verdict === 'NEEDS_REVISION');
const pick = reads[at === -1 ? reads.findIndex(r => r.score === score) : at];
const models = [...new Set(reads.map(r => r.model))];
const model = models.join(' and ');
const tally = reads.map(r => r.score).join(', ');
const line = stamp + ' | doctor ' + score + '/100 ' + verdict + ' | score only, no rewrite, ' + (READS === 1 ? '' : READS + ' reads (' + tally + '), ') + model;
const body = [
  'SCRIPT DOCTOR, SCORE ONLY' + (READS === 1 ? '' : ', STRICTEST OF ' + READS + ' READS') + ': ' + verdict + ' at ' + score + '/100 at ' + stamp + '. The script was not changed.',
  ...(recall ? ['TEE\'S RECORD: ' + recall + '.'] : []),
  ...(READS === 1 ? [] : ['READS: ' + reads.map((r, i) => (i + 1) + ' ' + r.verdict + ' ' + r.score).join(', ') + '. The lowest score is written, and PASS needs every read to pass at ' + FLOOR + ' or above.']),
  '',
  'DIAGNOSIS: ' + pick.diagnosis,
  '',
  ...(pick.preserved.length ? ['PRESERVED:', ...pick.preserved.map(p => '  - ' + p), ''] : []),
  ...(pick.notes.length ? ['NOTES:', ...pick.notes.map(n => '  - ' + n), ''] : []),
  ...(READS === 1 ? [] : ['OTHER READS:', ...reads.filter(r => r !== pick).map(r => '  - ' + r.verdict + ' ' + r.score + ': ' + (r.diagnosis || 'no diagnosis given'))])
].join('\n').trim();
// Ruled by Tee 2026-10-25, after execution 4364's note carried an en dash the
// doctor wrote: the doctor's words are quoted as written, never edited, and the
// note says how many em or en dashes they carry. Only the doctor's words shown
// in the note are counted: the lowest read's diagnosis, preserved list and
// notes, and the other reads' diagnoses. The TEE'S RECORD line comes from the
// recall and is not the doctor's (found by the verifier on e0351e1).
const DASH = new RegExp('[' + String.fromCharCode(0x2013, 0x2014) + ']', 'g');
const doctorWords = [pick.diagnosis, ...pick.preserved, ...pick.notes, ...(READS === 1 ? [] : reads.filter(r => r !== pick).map(r => r.diagnosis))].join('\n');
const dashes = (doctorWords.match(DASH) || []).length;
const feedback = body + (dashes ? '\n\nThe doctor\'s text above carries ' + dashes + ' dash' + (dashes === 1 ? '' : 'es') + ', quoted as it wrote ' + (dashes === 1 ? 'it' : 'them') + '.' : '');

return [{ json: { ...base, ok: true, verdict, score, line, feedback, model, reason: '' } }];

// Compose Write. Builds the two values Save Score Line writes from the row as it
// reads now, after the doctor call, and never from the copy read at the start
// of the run, so a line another lane appended in the meantime is kept. Score
// History and Last Feedback are appended to, the way Parse QC + Set Verdict
// appends. Nothing is written when the parse failed, when the row cannot be
// read back, when it left Scripted, when a doctor line landed during the run,
// or when any column the doctor's request was built from changed during the
// run. Those columns are compared as the row read at the start of the run and
// as it reads now, so a score always describes the row it lands on.
const p = $('Parse Score Only').first().json;
const DOCTOR = /\|\s*doctor\s+(\d+(?:\.\d+)?)\/100\s+([^|\n]*?)\s*(?=\||\n|$)/;
const skip = (reason) => [{ json: { ...p, ok: false, verdict: 'UNCHECKED', write: false, reason } }];
if (!p.ok) return [{ json: { ...p, write: false } }];
// A measurement run scores and writes nothing, and keeps the verdict and score
// for the run report.
if ($('Run Config').first().json.WRITE === false) {
  return [{ json: { ...p, write: false, measured: true, reason: 'a measurement run: Run Config WRITE is false, so nothing was written' } }];
}
const fresh = $input.all().map(i => i.json).filter(j => j && String(j.id) === String(p.rowId));
if (fresh.length !== 1) return skip('the row read back ' + fresh.length + ' time(s) before writing, and exactly 1 is required');
const r = fresh[0];
if (String(r.status) !== 'Scripted') return skip('the row moved to ' + JSON.stringify(r.status) + ' during the run');
if (DOCTOR.test(String(r.score_history || ''))) return skip('a doctor line landed on the row during the run');
// Every column Hydrate, Build Doctor Prompt, Doctor Sources and DEVON Recall:
// Ask read from the row.
const SHOWN = ['script', 'video_title', 'topic', 'description', 'learning_objective', 'broll_keywords', 'checklist', 'show', 'season', 'episode', 'idea', 'sources'];
const snap = $('One Idea at a Time').first().json;
const changed = SHOWN.filter(c => JSON.stringify(snap[c] ?? null) !== JSON.stringify(r[c] ?? null));
if (changed.length) {
  return skip(changed.join(', ') + ' changed on the row during the run, so the score is for a row it no longer describes');
}
const priorHistory = String(r.score_history || '');
const priorFeedback = String(r.last_feedback || '');
return [{ json: {
  ...p,
  write: true,
  scoreHistory: (priorHistory ? priorHistory + '\n' : '') + p.line,
  lastFeedback: (priorFeedback ? priorFeedback + '\n\n' : '') + p.feedback
} }];

// Confirm Write. Reads the row back after Save Score Line and checks both
// columns hold exactly what Compose Write sent. The run report counts a row as
// written only from this read, never from the update call returning success.
const c = $('Compose Write').first().json;
const back = $input.all().map(i => i.json).filter(j => j && String(j.id) === String(c.rowId));
const held = back.length === 1
  && String(back[0].score_history ?? '') === c.scoreHistory
  && String(back[0].last_feedback ?? '') === c.lastFeedback;
return [{ json: {
  show: c.show, rowId: c.rowId, title: c.title, ok: c.ok, verdict: c.verdict, score: c.score, line: c.line,
  written: held,
  reason: held ? '' : 'the write did not read back as sent (' + back.length + ' row(s) read back)'
} }];
